INSERT INTO products (id, name, slug, price_cents, stock, description, img_url, model_url, created_at, category_id, specs, tags, weight_g, sku) VALUES
('f06d3ba5-09f5-4c03-884f-d9e60207750c', 'Potentiometer Linear 10k', 'potentiometer-linear-10k', '3200', '34', 'The 10k potentiometer is a versatile variable resistor used in various electronic applications such as volume controls, dimmer switches, and sensor calibration. This potentiometer offers precise resistance adjustment with a total resistance of 10 kilohms. With its three-terminal design, it allows for easy integration into circuits, providing smooth and reliable control over voltage levels.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/d2e31273-c4f7-42d1-af3e-008f38106259.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/c82a4b96-9bd0-4f6e-b7fa-a9b184cb64bf.glb', '2026-02-05 18:12:35.284052', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('55d3634d-0091-4d95-a257-eed354ad0702', 'Arduino NANO Servo Shield', 'arduino-nano-servo-shield', '12200', '9', 'The Arduino Nano Servo Shield (or IO Expansion Shield) is a compact, plug-and-play breakout board designed to simplify wiring multiple servos and sensors to an Arduino Nano. It features dedicated 3-pin headers (GND, VCC, Signal) for up to 12-16 servo motors, separate external power inputs for servo motors, and breaks out all I/O pins for easy prototyping. ', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/f1aa509c-0257-4719-b856-91b414d2f4bf.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/aaae6f61-6de1-4f6a-897a-37bd2af5072a.glb', '2026-02-05 14:30:55.82466', 'f0bb3bd2-99dd-4f37-847a-af2dc873fe3e', '{}', '{}', NULL, NULL),
('e3e7befa-5c67-4391-b863-8687d1ae0d75', 'Resistors', 'resistors', '2500', '100', 'A resistor is an essential electronic component used to control the flow of electric current in a circuit. It helps regulate voltage, protect sensitive components, and ensure stable performance in electronic devices.\\n\\nDesigned for reliability and precision, resistors are commonly used in appliances, computers, mobile devices, and various electronic projects. They come in different resistance values and sizes to suit a wide range of circuit applications.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/1e270971-ee12-423f-9cbc-a7107b579e8d.png', NULL, '2026-03-10 05:49:34.91494', '2f688ac5-1cad-4146-b5cf-eb6d0a9dae94', '{}', '{}', NULL, NULL),
('0a7f9d9c-002c-4b8b-aa3c-6233c020b5c3', 'HC-05 Bluetooth Module', 'hc-05-bluetooth-module', '5900', '27', 'Bluetooth HC 05 Module is a Bluetooth mechanism that is particularly assembled for wireless communication. You can implement the module in either Master or Slave modes and switching between these two modes is quite easy. You will get the Slave mode configured by default. Further, the Slave mode can only accept connection but can''t initiate a connection to a Bluetooth-enabled device.AT command is provided to change the mode to either Master or Slave.\\n\\nPin Settings\\nAs far as the pin configurations are concerned, the Bluetooth serial module permits all serial-enabled circuits to communicate with each other via Bluetooth. There are 6 pins in total on the unit:\\n\\n1. Key/EN: You can use this pin to bring the Bluetooth module in AT commands. You can execute the module in the command mode with the Key/EN pin set in high. However, the unit will remain in data mode by default.\\n\\n2. VCC: You can connect 5V or 3.3V to this specific pin.\\n\\n3. GND: It is called the Ground pin on the module.\\n\\n4. TXD: This pin is used to transmit serial data received by the Bluetooth module.\\n\\n5. RXD: This pin allows you to receive data serially transmitted by a Bluetooth module.\\n\\n6. State: This pin indicated whether the module is connected or not.\\n\\nTo perform Bluetooth communications, you can send data from the smartphone terminal to the HC 05 Bluetooth Module and see it on the PC and vice versa. There are several Bluetooth terminal applications for Android and Windows in their respective app stores.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/cdc7cb90-0250-43a3-8005-4aee47e7e5e0.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/22c03c4a-1f9a-42a7-a14d-34857e70617a.glb', '2026-02-05 18:19:22.334063', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('6004ffc7-d262-40d5-93b8-41e861a6d3bf', 'Arduino UNO ', 'arduino-uno', '15900', '12', 'The Arduino Uno is a popular, open-source 8-bit microcontroller board based on the ATmega328P. It features 14 digital I/O pins (6 PWM), 6 analog inputs, a 16 MHz resonator, and a USB connection for programming. Designed for beginners and experts alike, it is easily powered via USB or a 7-20V adapter and used with the Arduino IDE. ', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/97407dbf-5adb-40e1-9124-eef85c166b23.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/7e5c4c6e-0d44-4584-acd1-d9c4203c33ec.glb', '2026-02-05 14:23:09.881072', 'f0bb3bd2-99dd-4f37-847a-af2dc873fe3e', '{}', '{}', NULL, NULL),
('6bce89f5-ffad-4c84-92bf-ba9c0254d1f6', 'Relay Module to 5V 10A', 'relay-module-to-5v-10a', '6500', '16', 'The Relay is a digital normally open switch that controls a relay capable of switching much higher voltages and currents than your normal Arduino boards. When set to HIGHT, the LED will light up and the relay will close allowing current to flow. The peak voltage capability is 250V at 10 amps.\\n\\nFeatures:\\n\\nControl Voltage: 5V\\nHIGHT level active\\nMax Control Capacity: 10A@250V AC\\nPackage List:\\n\\n1 x 1-Channel Relay Module-10A', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/26cf5f04-66a4-47cc-ad7f-14e8a61739ee.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/798a8853-d48b-45ef-9c19-8ec893020b73.glb', '2026-02-05 18:25:39.428286', '36225f90-95bf-485d-9808-acb8d7528135', '{}', '{}', NULL, NULL),
('5773bfda-ef03-4035-9e55-550c78189086', 'MB-102 Breadboard', 'mb-102-breadboard', '10200', '16', 'Easy to use: Our solderless breadboards are ideal for your prototypes, circuit design experiments and other DIY projects.\\n\\nEach row and column has corresponding letters and numbers, which makes it easier to use and prevents errors.\\n\\nPractical and reusable: The self-adhesive backing tape makes it easy to stick on a platform, as with the prototype sign\\n\\nWith tight plug-in contacts, the components sit well after assembly and there is no wobbling.\\n\\nOur plug-in boards do not need to be soldered and are therefore fully reusable. This makes it easy to create temporary prototypes and experiment with circuit design, which provides a design basis for prototype electronics.\\n\\nCompatible with resistors, transistors, diodes, LEDs, capacitors and other types of electronic components', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/56e799bb-79ba-4ed2-b9d3-c45cd617cceb.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/5678a96e-c44c-40b6-b56b-263ba75a9fac.glb', '2026-02-05 18:02:43.672079', 'f0bb3bd2-99dd-4f37-847a-af2dc873fe3e', '{}', '{}', NULL, NULL),
('07f84eca-04ae-4fbd-9e50-8ca62f83ab8a', 'Capacitors', 'capacitors', '3000', '100', 'Arduino capacitors are electronic components commonly used in Arduino circuits to store and release electrical energy. They help stabilize voltage, filter noise, smooth power supply signals, and manage timing functions in electronic projects.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/98e6dd6c-72ea-4c9d-9184-e8f406af46c0.png', NULL, '2026-03-10 06:33:06.157715', '2f688ac5-1cad-4146-b5cf-eb6d0a9dae94', '{}', '{}', NULL, NULL),
('ff47bb9b-029c-4260-95f8-55dfb77243f3', 'Sound Sensor', 'sound-sensor', '5900', '100', 'Detect sound levels easily with this sound sensor module for Arduino projects. It can sense claps, noise, or vibrations and convert them into signals for your Arduino board. Perfect for sound-activated lights, alarms, and interactive DIY electronics projects.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/422a6325-7737-4119-b177-1e6ecb102138.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/2041023f-b946-4f97-9383-1536809a0ac0.glb', '2026-03-10 07:49:25.38313', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('639dc664-12af-4e16-9ae7-f4e3c1a2136e', 'Temperature Module', 'temperature-module', '3900', '98', 'Monitor temperature easily with this temperature sensor module for Arduino projects. It provides accurate temperature readings that can be used for weather stations, smart systems, and monitoring applications. Simple to connect and compatible with most Arduino boards, making it perfect for beginners and electronics enthusiasts', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/e21fae93-99f7-484f-8d88-ed50d972a412.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/cea93ac8-84f0-4c5b-832d-f5df2f39bda7.glb', '2026-03-10 07:31:38.483122', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('fd165f0d-b345-4395-ae2c-3ca8a863ddf2', 'IR Sensor ', 'ir-sensor', '4900', '100', 'Detect objects and measure distance easily with this reliable IR Sensor. It is commonly used in Arduino projects for obstacle detection, line tracking, and automation systems. Simple to connect and compatible with most Arduino boards, this sensor is perfect for beginners and electronics enthusiasts.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/44234c82-c862-4e2a-8f5f-b548bab0ba7d.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/0a344110-96f9-4df9-a5af-709af9929d76.glb', '2026-03-10 07:15:05.383051', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('4f7a2bf3-084a-413d-8181-133aafa3c612', 'Buzzer', 'buzzer', '5900', '100', 'Add sound alerts and simple audio signals to your Arduino projects with this buzzer module. It is perfect for alarms, notifications, and interactive electronics. Easy to connect and compatible with most Arduino boards, making it great for beginners and DIY electronics projects.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/e2d480dc-f37f-4507-99f9-7c8dcb8e0fca.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/a19fbe31-6ed2-447e-9e06-549e895e79e0.glb', '2026-03-10 07:27:38.430723', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('3d3a4f22-1aac-45ac-b25c-73b9c523c37e', 'Male to Male Jumper Wires', 'male-to-male-jumper-wires', '2500', '99', 'Male-to-male jumper wires are electrical connection cables used in Arduino and breadboard projects to easily link components together without soldering. Each wire has male pin connectors on both ends, allowing them to plug directly into breadboards, Arduino headers, and other electronic modules.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/b240c690-388d-4830-8b12-ec1f0a2ef308.png', NULL, '2026-03-10 06:37:05.83519', '2f688ac5-1cad-4146-b5cf-eb6d0a9dae94', '{}', '{}', NULL, NULL),
('ad6d9092-30c4-46e2-a3a9-c7d0537b126b', '16 x 2 LCD Display', '16-x-2-lcd-display', '14900', '23', 'Display text and simple information easily with this 16×2 LCD module for Arduino. It can show up to 16 characters on 2 lines, making it perfect for displaying sensor data, messages, and project status. Easy to connect and widely used in Arduino projects, it is great for both beginners and advanced makers', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/06419f6d-9d1d-4855-9759-82c79bf466bb.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/f81abdff-48e2-4ae3-b932-9da5484552ce.glb', '2026-03-10 07:20:07.287718', 'f0bb3bd2-99dd-4f37-847a-af2dc873fe3e', '{}', '{}', NULL, NULL),
('3a10d52f-9131-403b-a1ea-1004fd685cc4', 'Ultrasonic Sensor', 'ultrasonic-sensor', '29900', '98', 'Measure distance and detect objects with this ultrasonic sensor for Arduino projects. It uses sound waves to accurately calculate distance, making it perfect for obstacle detection, robotics, and automation systems. Easy to connect and widely used by beginners and hobbyists in DIY electronics.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/43c86d7d-8451-46a7-9245-22d197e1e802.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/12541e28-4d8b-4358-a23f-de6cfc2a5a1d.glb', '2026-03-10 07:37:17.352039', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('e86d8889-61d6-4e97-a3a2-344a852b6efa', 'Motion Sensor', 'motion-sensor', '6900', '99', 'Detect movement easily with this PIR motion sensor for Arduino projects. It senses infrared changes from people or objects and triggers a signal when motion is detected. Perfect for security systems, automatic lights, and smart home DIY projects.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/86dc093b-a396-4ed6-bfa8-dec762e7808a.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/c34a6abd-c4fc-4e53-b579-7f4ad1a1e947.glb', '2026-03-10 07:59:40.756476', 'f170f920-3d0a-4eda-a33f-52d81dc5b3a2', '{}', '{}', NULL, NULL),
('75a67a8c-a785-4ac9-9502-51e353a71a0f', 'Led Lights', 'led-lights', '500', '99', 'Brighten your Arduino projects with this high-quality LED. It is perfect for beginners and hobbyists who want to add simple lighting indicators or visual effects to their circuits. Easy to connect and compatible with most Arduino boards, this LED is ideal for learning electronics and creating fun DIY projects. ', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/f99a6818-5a4f-4197-af19-2274bfb5a932.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/0ad6aad9-bdc9-4310-96fd-edb12a6efc1a.glb', '2026-03-10 06:58:27.464601', '2f688ac5-1cad-4146-b5cf-eb6d0a9dae94', '{}', '{}', NULL, NULL),
('9a6bbf2c-b515-4e11-b403-9d1d3b7a2fa8', 'Wifi Module ESP32', 'wifi-module-esp32', '37900', '96', 'The ESP32 WiFi Module is a powerful and versatile microcontroller with built-in WiFi and Bluetooth connectivity. It is ideal for IoT projects, smart devices, and wireless communication applications.\\n\\nDesigned for efficiency and performance, the ESP32 allows developers and hobbyists to easily connect their projects to the internet, control devices remotely, and build smart systems using platforms like Arduino IDE and MicroPython.', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/e7bb5e18-f5c3-4c9f-957b-2f78910087d2.png', 'https://tyhocgrjwxswxzzfvwct.supabase.co/storage/v1/object/public/models/ba8ec5a2-ff90-4ab1-9d44-fc134444bf22.glb', '2026-03-10 08:18:47.745297', 'f0bb3bd2-99dd-4f37-847a-af2dc873fe3e', '{}', '{}', NULL, NULL);
